module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output reg Q
);

    always @(posedge clk) begin
        if (L)
            Q <= r_in;
        else
            Q <= q_in;
    end

endmodule

module TopModule(
    input  logic clk,
    input  logic d,
    output wire  q
);

    logic q_pos, q_neg;

    always_ff @(posedge clk) begin
        q_pos <= d;
    end

    always_ff @(negedge clk) begin
        q_neg <= d;
    end

    assign q = clk ? q_pos : q_neg;

endmodule
